export const getUploadModFileUrl = (modId: string,) => {




  return `/api/mods/${modId}/files`
}

/**
 * Requires a signed-in author. Accepts one .jar file and supported Minecraft versions. Files are not published unless the scan is clean.
 * @summary Upload and scan a mod file
 */
export const uploadModFile = async (modId: string,
    modFileUploadInput: ModFileUploadInput, options?: Parameters<typeof customFetch>[1]): Promise<ModFile> => {
    const formData = new FormData();
formData.append(`file`, modFileUploadInput.file);
formData.append(`minecraftVersions`, modFileUploadInput.minecraftVersions);

  return customFetch<ModFile>(getUploadModFileUrl(modId),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





